/** One leaf of an opened grammar: what it takes, and where a token it takes goes. */
export interface GrammarLeaf {
  readonly longhands: readonly string[];
  /** Keywords it takes, exactly. */
  readonly words: readonly string[];
  /** Primitive types it takes — `length`, `color`, `custom-ident`. */
  readonly types: readonly string[];
  /** Functions it takes, by name. */
  readonly functions: readonly string[];
  /** It takes a free identifier, so it stands down for any leaf that NAMES the token. */
  readonly open: boolean;
}

/** One family: the grammar a value is read against, and a leaf description per leaf of it. */
export interface GrammarShape {
  readonly longhands: readonly string[];
  /** The opened grammar of ONE value, or of one ITEM where {@link GrammarShape.list} is set. */
  readonly tree: Term;
  /** One per leaf of `tree`, in the order a pre-order walk reaches them. */
  readonly leaves: readonly GrammarLeaf[];
  /** A COMMA-separated family: every item takes this shape, and each longhand is a list. */
  readonly list?: boolean;
}

